1	<title>Nxeon Hosting — console redesign</title>
2	<style>
3	  :root{
4	    --ground:#080b16; --ground-2:#0b1020; --rail:#0a0e1c;
5	    --panel:#0f152a; --panel-2:#131a33; --panel-hi:#182142;
6	    --line:rgba(255,255,255,.07); --line-2:rgba(255,255,255,.13);
7	    --text:#eef1fb; --muted:#98a2c0; --faint:#68738f;
8	    --violet:#8b5cf6; --violet-2:#a78bfa; --cyan:#22d3ee; --cyan-2:#67e8f9;
9	    --emerald:#34d399; --amber:#fbbf24; --rose:#fb7185;
10	    --grad:linear-gradient(120deg,#8b5cf6,#22d3ee);
11	    --mono:ui-monospace,"SF Mono","JetBrains Mono",Menlo,monospace;
12	    --sans:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
13	  }
14	  *{box-sizing:border-box;margin:0;padding:0}
15	  body{font-family:var(--sans);color:var(--text);background:var(--ground);-webkit-font-smoothing:antialiased;
16	    background-image:radial-gradient(60rem 44rem at 76% -12%,rgba(139,92,246,.10),transparent 60%),
17	                     radial-gradient(48rem 40rem at 100% 8%,rgba(34,211,238,.07),transparent 55%);}
18	  .shell{display:grid;grid-template-columns:236px 1fr;min-height:100vh}
19	  a{color:inherit;text-decoration:none}
20	  ::-webkit-scrollbar{width:9px;height:9px}::-webkit-scrollbar-thumb{background:#1b2542;border-radius:9px}
21	
22	  /* ---------- left nav ---------- */
23	  .side{background:var(--rail);border-right:1px solid var(--line);display:flex;flex-direction:column;position:sticky;top:0;height:100vh;overflow-y:auto}
24	  .logo{display:flex;align-items:center;gap:10px;padding:18px 18px 14px}
25	  .logo .m{width:30px;height:30px;border-radius:9px;background:var(--grad);display:grid;place-items:center;font-weight:800;color:#0a0e1a;font-size:14px}
26	  .logo b{font-size:16px;letter-spacing:.02em}
27	  .navg{padding:6px 12px}
28	  .navg .h{font-size:10px;letter-spacing:.16em;color:var(--faint);padding:14px 10px 6px;font-weight:700}
29	  .navg a{display:flex;align-items:center;gap:11px;padding:8.5px 10px;border-radius:9px;color:var(--muted);font-size:13px;font-weight:500;cursor:pointer;margin:1px 0}
30	  .navg a:hover{background:var(--panel);color:var(--text)}
31	  .navg a.on{background:linear-gradient(90deg,rgba(139,92,246,.22),rgba(34,211,238,.05));color:#fff;box-shadow:inset 0 0 0 1px rgba(139,92,246,.28)}
32	  .navg a .i{width:17px;text-align:center;opacity:.9;font-size:14px}
33	  .side .bal{margin-top:auto;border-top:1px solid var(--line);padding:14px 18px}
34	  .side .bal .k{font-size:10px;letter-spacing:.12em;color:var(--faint);font-weight:700}
35	  .side .bal .v{font-size:20px;font-weight:800;letter-spacing:-.02em;margin-top:3px;background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}
36	  .side .bal .u{font-size:11.5px;color:var(--faint);margin-top:10px}
37	  .side .bal .u2{font-size:12px;color:var(--muted);margin-top:8px;cursor:pointer;display:flex;align-items:center;gap:7px}
38	
39	  /* ---------- top bar ---------- */
40	  .main{display:flex;flex-direction:column;min-width:0}
41	  .top{height:64px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:16px;padding:0 24px;position:sticky;top:0;background:rgba(8,11,22,.82);backdrop-filter:blur(10px);z-index:10}
42	  .search{flex:1;max-width:520px;display:flex;align-items:center;gap:10px;background:var(--panel);border:1px solid var(--line);border-radius:11px;padding:9px 13px;color:var(--faint);font-size:13px}
43	  .search .kbd{margin-left:auto;font-family:var(--mono);font-size:11px;border:1px solid var(--line-2);border-radius:6px;padding:1px 6px;color:var(--muted)}
44	  .top .sp{flex:1}
45	  .refer{display:flex;align-items:center;gap:7px;font-size:12.5px;color:var(--violet-2);border:1px solid rgba(139,92,246,.3);background:rgba(139,92,246,.08);padding:7px 12px;border-radius:10px;cursor:pointer}
46	  .bell{position:relative;width:38px;height:38px;border-radius:10px;border:1px solid var(--line);display:grid;place-items:center;cursor:pointer;color:var(--muted)}
47	  .bell .n{position:absolute;top:-5px;right:-5px;background:var(--violet);color:#fff;font-size:10px;font-weight:700;border-radius:99px;padding:1px 5px}
48	  .prof{display:flex;align-items:center;gap:10px;cursor:pointer}
49	  .prof .av{width:36px;height:36px;border-radius:10px;background:linear-gradient(135deg,#7c5cff,#22d3ee);display:grid;place-items:center;font-weight:700;color:#0a0e1a}
50	  .prof small{display:block;color:var(--faint);font-size:11px}
51	  .prof b{font-size:13px}
52	
53	  .wrap{display:grid;grid-template-columns:1fr 296px;gap:22px;padding:24px;align-items:start}
54	  @media(max-width:1180px){.wrap{grid-template-columns:1fr}.rail{display:none}}
55	  @media(max-width:820px){.shell{grid-template-columns:1fr}.side{display:none}}
56	
57	  /* ---------- page head ---------- */
58	  .phead{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:18px}
59	  .phead h1{font-size:23px;letter-spacing:-.02em}
60	  .phead .sp{flex:1}
61	  .btn{border:1px solid var(--line-2);background:var(--panel);color:var(--text);font-weight:600;font-size:13px;padding:9px 14px;border-radius:11px;cursor:pointer;display:inline-flex;align-items:center;gap:8px;white-space:nowrap}
62	  .btn:hover{border-color:rgba(255,255,255,.24);background:var(--panel-2)}
63	  .btn.primary{border:none;background:var(--grad);color:#0a0e1a}
64	  .btn.cyan{border-color:rgba(34,211,238,.35);color:var(--cyan-2);background:rgba(34,211,238,.07)}
65	  .btn.sm{padding:6px 11px;font-size:12px;border-radius:9px}
66	  .btn.block{width:100%;justify-content:flex-start}
67	
68	  .planbar{display:inline-flex;align-items:center;gap:10px;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:9px 14px;cursor:pointer;margin-bottom:18px}
69	  .planbar .pd{width:26px;height:26px;border-radius:7px;background:linear-gradient(135deg,#7c5cff,#22d3ee)}
70	  .planbar b{font-size:13.5px}
71	  .tag{font-size:10.5px;font-weight:700;padding:2px 8px;border-radius:99px;letter-spacing:.02em}
72	  .tag.pro{color:var(--violet-2);background:rgba(139,92,246,.14);border:1px solid rgba(139,92,246,.3)}
73	  .tag.live{color:var(--emerald);background:rgba(52,211,153,.1);border:1px solid rgba(52,211,153,.28)}
74	  .tag.primary{color:#fff;background:rgba(255,255,255,.13);border:1px solid var(--line-2)}
75	  .tag.wp{color:var(--cyan-2);background:rgba(34,211,238,.12);border:1px solid rgba(34,211,238,.3)}
76	  .tag.static{color:#c3ccdf;background:rgba(148,163,184,.14);border:1px solid var(--line-2)}
77	
78	  /* ---------- stat cards ---------- */
79	  .stats{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:20px}
80	  @media(max-width:1180px){.stats{grid-template-columns:repeat(3,1fr)}}
81	  @media(max-width:640px){.stats{grid-template-columns:repeat(2,1fr)}}
82	  .stat{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:15px}
83	  .stat .r1{display:flex;align-items:center;gap:10px}
84	  .stat .ic{width:34px;height:34px;border-radius:9px;background:var(--panel-hi);display:grid;place-items:center;font-size:15px}
85	  .stat .k{font-size:12px;color:var(--muted)}
86	  .stat .v{font-size:19px;font-weight:800;letter-spacing:-.01em;margin:9px 0}
87	  .stat .v small{font-size:12.5px;color:var(--faint);font-weight:500}
88	  .bar{height:6px;border-radius:99px;background:rgba(255,255,255,.08);overflow:hidden}
89	  .bar>i{display:block;height:100%;background:var(--grad);border-radius:99px}
90	  .stat .lnk{font-size:12px;color:var(--violet-2);font-weight:600;margin-top:11px;display:inline-block;cursor:pointer}
91	
92	  /* ---------- toolbar ---------- */
93	  .toolbar{display:flex;align-items:center;gap:12px;margin-bottom:16px}
94	  .field{display:flex;align-items:center;gap:9px;background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:8px 12px;color:var(--faint);font-size:13px}
95	  .field.grow{flex:1;max-width:340px}
96	  .field select,.field input{background:none;border:none;color:var(--text);font-family:inherit;font-size:13px;outline:none}
97	  .segtoggle{margin-left:auto;display:flex;border:1px solid var(--line);border-radius:9px;overflow:hidden}
98	  .segtoggle button{background:var(--panel);border:none;color:var(--faint);padding:7px 10px;cursor:pointer}
99	  .segtoggle button.on{background:var(--panel-hi);color:#fff}
100	
101	  /* ---------- website cards ---------- */
102	  .grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(290px,1fr));gap:16px}
103	  .site{background:var(--panel);border:1px solid var(--line);border-radius:15px;overflow:hidden;transition:transform .12s,border-color .12s,box-shadow .12s}
104	  .site:hover{transform:translateY(-3px);border-color:rgba(139,92,246,.42);box-shadow:0 20px 42px -24px rgba(0,0,0,.85)}
105	  .site .body{display:flex;gap:13px;padding:14px}
106	  .thumb{width:72px;height:56px;border-radius:9px;flex:none;display:grid;place-items:center;font-size:24px;border:1px solid var(--line);overflow:hidden}
107	  .site .hd{min-width:0;flex:1}
108	  .site .hn{display:flex;align-items:center;gap:7px;flex-wrap:wrap}
109	  .site .hn b{font-family:var(--mono);font-size:13px;font-weight:600;letter-spacing:-.01em;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:150px}
110	  .site .app{display:flex;align-items:center;gap:7px;margin-top:8px;color:var(--muted);font-size:12px}
111	  .dotlive{width:7px;height:7px;border-radius:50%;background:var(--emerald);box-shadow:0 0 8px var(--emerald);display:inline-block}
112	  .site .metrics{display:flex;gap:14px;padding:0 14px 12px;color:var(--faint);font-size:11.5px;flex-wrap:wrap}
113	  .site .metrics span{display:inline-flex;align-items:center;gap:5px}
114	  .site .foot{display:flex;gap:8px;padding:12px 14px;border-top:1px solid var(--line);background:var(--panel-2)}
115	  .site .foot .btn{flex:1;justify-content:center}
116	  .kebab{width:38px;flex:none!important}
117	  .addcard{border:1.5px dashed var(--line-2);background:transparent;display:grid;place-items:center;min-height:210px;gap:9px;border-radius:15px;color:var(--muted);cursor:pointer;text-align:center;padding:20px}
118	  .addcard:hover{border-color:var(--violet);color:#fff}
119	  .addcard .plus{width:46px;height:46px;border-radius:13px;background:rgba(139,92,246,.12);border:1px solid rgba(139,92,246,.3);display:grid;place-items:center;font-size:22px;color:var(--violet-2)}
120	
121	  /* ---------- bottom panels ---------- */
122	  .btm{display:grid;grid-template-columns:1.15fr 1fr 1fr;gap:16px;margin-top:22px}
123	  @media(max-width:1000px){.btm{grid-template-columns:1fr}}
124	  .card{background:var(--panel);border:1px solid var(--line);border-radius:15px;padding:17px}
125	  .card h3{font-size:13.5px;margin-bottom:14px;display:flex;align-items:center;gap:8px}
126	  .card h3 .sp{flex:1}.card h3 a{font-size:12px;color:var(--violet-2);font-weight:600;cursor:pointer}
127	  .act .li{display:flex;gap:11px;align-items:flex-start;padding:9px 0;border-top:1px solid var(--line);font-size:12.5px;color:var(--muted)}
128	  .act .li:first-child{border-top:none}
129	  .act .li .d{width:24px;height:24px;border-radius:7px;background:var(--panel-hi);display:grid;place-items:center;font-size:12px;flex:none}
130	  .act .li b{color:var(--text);font-weight:600}
131	  .act .li time{margin-left:auto;color:var(--faint);font-size:11px;white-space:nowrap}
132	  .row{display:flex;justify-content:space-between;align-items:center;padding:9px 0;border-top:1px solid var(--line);font-size:13px}
133	  .row:first-of-type{border-top:none}.row .k{color:var(--muted)}.row .v{font-weight:600}
134	  .usage .u{margin:12px 0}
135	  .usage .u .t{display:flex;justify-content:space-between;font-size:12px;color:var(--muted);margin-bottom:6px}
136	  .usage .u .t b{color:var(--text)}
137	  .barC>i{background:linear-gradient(90deg,#34d399,#22d3ee)}
138	  .barW>i{background:linear-gradient(90deg,#a78bfa,#8b5cf6)}
139	  .barA>i{background:linear-gradient(90deg,#22d3ee,#a78bfa)}
140	
141	  /* ---------- right rail ---------- */
142	  .rail{display:flex;flex-direction:column;gap:16px;position:sticky;top:88px}
143	  .rail .card h3{margin-bottom:12px}
144	  .feat{display:flex;align-items:center;gap:9px;font-size:12.5px;color:var(--muted);padding:6px 0}
145	  .feat .c{color:var(--emerald)}
146	  .qa{display:flex;flex-direction:column;gap:7px}
147	  .help{text-align:center}
148	  .help p{color:var(--muted);font-size:12.5px;margin:6px 0 13px}
149	
150	  /* ---------- website DETAIL view ---------- */
151	  #detail{display:none}
152	  .dhead{display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin-bottom:6px}
153	  .crumb{color:var(--faint);font-size:12.5px;margin-bottom:16px}
154	  .crumb .c{cursor:pointer}.crumb .c:hover{color:var(--muted)}
155	  .dhead .fav{width:54px;height:54px;border-radius:13px;background:var(--panel-hi);border:1px solid var(--line-2);display:grid;place-items:center;font-size:26px;flex:none}
156	  .dhead h1{font-family:var(--mono);font-size:21px;letter-spacing:-.02em}
157	  .dhead .pills{display:flex;gap:8px;margin-top:9px;flex-wrap:wrap}
158	  .pill{font-size:11.5px;font-weight:600;padding:4px 10px;border-radius:99px;border:1px solid var(--line);color:var(--muted);display:inline-flex;align-items:center;gap:6px}
159	  .pill.ok{color:var(--emerald);border-color:rgba(52,211,153,.3);background:rgba(52,211,153,.08)}
160	  .pill.wp{color:var(--cyan-2);border-color:rgba(34,211,238,.3);background:rgba(34,211,238,.07)}
161	  .subnav{display:flex;gap:3px;margin:22px 0 20px;border-bottom:1px solid var(--line);overflow-x:auto}
162	  .subnav button{background:none;border:none;color:var(--muted);font-family:inherit;font-size:13.5px;font-weight:600;padding:11px 14px;cursor:pointer;border-bottom:2px solid transparent;white-space:nowrap}
163	  .subnav button:hover{color:var(--text)}.subnav button.on{color:#fff;border-bottom-color:var(--violet)}
164	  .cols{display:grid;grid-template-columns:1.6fr 1fr;gap:16px;align-items:start}
165	  @media(max-width:900px){.cols{grid-template-columns:1fr}}
166	  .cred{background:var(--ground-2);border:1px solid var(--line);border-radius:11px;padding:6px 14px;margin-top:8px}
167	  .lnk{color:var(--violet-2);font-weight:600;cursor:pointer}
168	  .ph{color:var(--faint);font-size:13px;padding:30px;text-align:center;border:1px dashed var(--line-2);border-radius:14px}
169	  .note{font-size:11.5px;color:var(--faint);margin-top:9px}
170	  .vmono{font-family:var(--mono);font-size:12.5px}
171	</style>
172	
173	<div class="shell">
174	  <!-- LEFT NAV -->
175	  <aside class="side">
176	    <div class="logo"><span class="m">N</span><b>NXEON</b></div>
177	    <div class="navg">
178	      <div class="h">MAIN</div>
179	      <a><span class="i">▦</span> Dashboard</a>
180	      <a class="on"><span class="i">🖥️</span> Hosting</a>
181	      <a><span class="i">🌐</span> Domains</a>
182	      <a><span class="i">✉️</span> Emails</a>
183	      <a><span class="i">🗂️</span> Websites</a>
184	      <a><span class="i">🗄️</span> Databases</a>
185	      <a><span class="i">↺</span> Backups</a>
186	      <a><span class="i">🔒</span> SSL Certificates</a>
187	      <div class="h">TOOLS</div>
188	      <a><span class="i">📁</span> File Manager</a>
189	      <a><span class="i">📜</span> Logs</a>
190	      <a><span class="i">⇄</span> Migration Center</a>
191	      <a><span class="i">⏱️</span> Cron Jobs</a>
192	      <a><span class="i">🛡️</span> Security</a>
193	      <div class="h">BILLING</div>
194	      <a><span class="i">📋</span> My Plan</a>
195	      <a><span class="i">⬆️</span> Upgrade</a>
196	      <a><span class="i">🧾</span> Invoices</a>
197	    </div>
198	    <div class="bal">
199	      <div class="k">ACCOUNT BALANCE</div>
200	      <div class="v">$4,380.26</div>
201	      <div class="u">nicholas.albanese@gmail.com</div>
202	    </div>
203	  </aside>
204	
205	  <!-- MAIN -->
206	  <div class="main">
207	    <!-- TOP BAR -->
208	    <div class="top">
209	      <div class="search">🔍 Search websites, domains, databases… <span class="kbd">⌘K</span></div>
210	      <div class="sp"></div>
211	      <div class="refer">🎁 Refer &amp; earn</div>
212	      <div class="bell">🔔<span class="n">8</span></div>
213	      <div class="prof"><span class="av">N</span><div><b>Nicholas A.</b><small>Business Pro</small></div></div>
214	    </div>
215	
216	    <div id="page-hub" class="wrap">
217	      <!-- ===== HUB main column ===== -->
218	      <div>
219	        <div class="phead">
220	          <h1>My Hosting Plans</h1>
221	          <div class="sp"></div>
222	          <button class="btn" onclick="soon('Upgrade plan')">⬆️ Upgrade Plan</button>
223	          <button class="btn cyan" onclick="soon('Upgrade storage')">💾 Upgrade Storage</button>
224	          <button class="btn primary" onclick="soon('Add website')">＋ Add Website</button>
225	        </div>
226	
227	        <div class="planbar" onclick="soon('Switch plan')">
228	          <span class="pd"></span><b>Business Pro Plan</b><span class="tag pro">PRO</span><span class="tag live">● Active</span><span style="color:var(--faint)">⌄</span>
229	        </div>
230	
231	        <div class="stats">
232	          <div class="stat"><div class="r1"><span class="ic">🌐</span><span class="k">Websites</span></div><div class="v">8 <small>/ 20</small></div><div class="bar"><i style="width:40%"></i></div><span class="lnk">Manage →</span></div>
233	          <div class="stat"><div class="r1"><span class="ic">🔗</span><span class="k">Domains</span></div><div class="v">9</div><div class="bar"><i style="width:45%"></i></div><span class="lnk">Manage →</span></div>
234	          <div class="stat"><div class="r1"><span class="ic">💾</span><span class="k">Storage</span></div><div class="v">18.4 <small>/ 50 GB</small></div><div class="bar"><i style="width:36%"></i></div><span class="lnk">Upgrade →</span></div>
235	          <div class="stat"><div class="r1"><span class="ic">🗄️</span><span class="k">Databases</span></div><div class="v">6 <small>/ 20</small></div><div class="bar"><i style="width:30%"></i></div><span class="lnk">Manage →</span></div>
236	          <div class="stat"><div class="r1"><span class="ic">✉️</span><span class="k">Emails</span></div><div class="v">21 <small>/ 100</small></div><div class="bar"><i style="width:21%"></i></div><span class="lnk">Manage →</span></div>
237	        </div>
238	
239	        <div class="toolbar">
240	          <div class="field grow">🔍 <input placeholder="Search websites…"></div>
241	          <div class="field"><select><option>All Status</option><option>Active</option><option>Pending DNS</option></select></div>
242	          <div class="segtoggle"><button class="on">▦</button><button>≡</button></div>
243	        </div>
244	
245	        <div class="grid" id="siteGrid"></div>
246	
247	        <div class="btm">
248	          <div class="card act"><h3>Recent Activity <span class="sp"></span><a>View all logs →</a></h3>
249	            <div class="li"><span class="d">🅦</span><div><b>WordPress installed</b> on shop.cozeypaws.com</div><time>2m</time></div>
250	            <div class="li"><span class="d">🗄️</span><div>Database <b>cozeypaws_db</b> created</div><time>1h</time></div>
251	            <div class="li"><span class="d">🔒</span><div>SSL renewed for <b>cozeypaws.com</b></div><time>3h</time></div>
252	            <div class="li"><span class="d">↺</span><div>Backup completed</div><time>5h</time></div>
253	            <div class="li"><span class="d">✉️</span><div><b>info@cozeypaws.com</b> created</div><time>1d</time></div>
254	          </div>
255	          <div class="card"><h3>Plan Information</h3>
