349	/**
350	 * DNS→HTTPS stepper driven by the REAL serve-verification the worker records
351	 * (serveHttpOk / serveHttpsOk / sslActive), so it can never claim "live" while
352	 * HTTPS actually refuses. Three overall states, per the account's measured health:
353	 *   • verified — a trusted cert is live (sslActive) and 443 answers → "HTTPS live ✓"
354	 *   • issuing  — the site answers (self-signed 443 or HTTP) but no trusted cert yet
355	 *   • dns      — nothing answers for the domain yet (DNS not pointed at us)
356	 */
357	function DnsStepper({ account }: { account: HostingAccountView }) {
358	  const checked = account.healthCheckedAt != null || account.serveHttpOk != null;
359	  const serving = account.serveHttpOk === true || account.serveHttpsOk === true;
360	  const verified = account.sslActive && account.serveHttpsOk !== false;
361	  const state: "verified" | "issuing" | "dns" | "pending" =
362	    verified ? "verified" : serving ? "issuing" : checked ? "dns" : "pending";
363	
364	  const free = account.isFreeSubdomain;
365	  const steps = [
366	    { label: free ? "DNS ready" : "Point domain", done: true, hint: free ? "Set up automatically" : "Add the A record above" },
367	    {
368	      label: "Site live",
369	      done: state === "issuing" || state === "verified",
370	      hint: state === "issuing" || state === "verified" ? "Serving traffic" : state === "dns" ? "DNS not detected yet" : "Checking…",
371	    },
372	    {
373	      label: "HTTPS verified",
374	      done: state === "verified",
375	      hint: state === "verified" ? "Certificate trusted" : state === "issuing" ? "Issuing certificate" : "Auto after DNS",
376	    },
377	  ];
378	
379	  const headline =
380	    account.healthNote ??
381	    (state === "verified" ? "HTTPS live — verified" : state === "issuing" ? "HTTP live, HTTPS issuing" : state === "dns" ? "DNS not detected yet" : "Not checked yet");
382	  const headlineTone = state === "verified" ? "text-emerald-300" : state === "dns" ? "text-slate-400" : "text-amber-300";
383	
384	  return (
385	    <div className="mt-4">
386	      <div className="flex items-center">
387	        {steps.map((s, i) => (
388	          <div key={s.label} className="flex flex-1 items-center last:flex-none">
389	            <div className="flex flex-col items-center">
390	              <span className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] ${s.done ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300" : "border-amber-500/40 bg-amber-500/10 text-amber-300"}`}>
391	                {s.done ? "✓" : i + 1}
392	              </span>
393	            </div>
394	            {i < steps.length - 1 && <div className={`mx-2 h-px flex-1 ${steps[i + 1].done ? "bg-emerald-500/40" : "bg-white/10"}`} />}
395	          </div>
396	        ))}
397	      </div>
398	      <div className="mt-1.5 flex items-start justify-between text-[11px]">
399	        {steps.map((s) => (
400	          <div key={s.label} className="flex-1 text-center first:text-left last:text-right">
401	            <p className={s.done ? "text-emerald-300" : "text-slate-400"}>{s.label}</p>
402	            <p className="text-slate-500">{s.hint}</p>
403	          </div>
404	        ))}
405	      </div>
406	      <p className={`mt-3 text-xs font-medium ${headlineTone}`}>
407	        {headline}
408	        {account.healthCheckedAt && (
409	          <span className="ml-1 font-normal text-slate-500">· checked {new Date(account.healthCheckedAt).toLocaleTimeString()}</span>
410	        )}
411	      </p>
412	      {state !== "verified" && (
413	        <p className="mt-1 text-xs text-slate-500">
414	          {free ? (
415	            <>A trusted HTTPS certificate is issued automatically once provisioning completes — this usually takes a minute. Use <span className="text-slate-300">Refresh</span> to check right away.</>
416	          ) : (
417	            <>A trusted HTTPS certificate is issued automatically once your domain resolves to us — this can take a few minutes after you set the DNS record. Use <span className="text-slate-300">Go live</span> to check right away.</>
418	          )}
419	        </p>
420	      )}
421	    </div>
422	  );
423	}
