"use client";

import { useCallback, useEffect, useRef, useState, type ReactNode } from "react";
import {
  getHostingAccount,
  revealHostingSftpPassword,
  recheckHostingHealth,
  renameHostingAccount,
  listWebsites,
  listHostingDatabases,
  listHostingBackups,
  listHostingSubdomains,
  listHostingAddonDomains,
  listHostingTaskLog,
  installWordPress,
  installApp,
  listAppCatalog,
  setPrimaryHostingDomain,
  deleteSubdomain,
  deleteAddonDomain,
  type HostingAccountView,
  type HostingWebsiteView,
  type SiteTarget,
} from "@/lib/actions-hosting";
import { getHostingEmailStatus } from "@/lib/hosting-email";
import { Badge, StatusDot } from "@/components/ui/primitives";
import { QuotaTile } from "./shared";
import { AppCredentials } from "./AppCredentials";
import { FileManager } from "./FileManager";
import { Backups } from "./Backups";
import { AppInstaller } from "./AppInstaller";
import { DatabasesPanel } from "./DatabasesPanel";
import { PhpSwitcher } from "./PhpSwitcher";
import { SubdomainsPanel } from "./SubdomainsPanel";
import { AddonDomainsPanel } from "./AddonDomainsPanel";
import { CronPanel } from "./CronPanel";
import { EmailTab } from "./EmailTab";
import { HostingUpgradePanel } from "./HostingUpgradePanel";

/* ==========================================================================
 * Hosting console — the plan-as-workspace shell.
 *
 * Two views, both URL-addressable so links survive a refresh:
 *   • PLAN CONSOLE (default)  — header + resource stat-cards (the primary nav) +
 *     the website grid (the hub) + Activity / Plan / Usage + a slim connection rail.
 *     Plan-scoped resource SECTIONS (Databases, Email, Backups, Domains, Files,
 *     Cron, Logs, Settings) reuse the existing panels verbatim, reached from the
 *     stat-cards and a secondary in-plan nav.  URL: `?tab=<section>`.
 *   • WEBSITE DETAIL          — scoped to ONE website (primary / subdomain / addon)
 *     with its own sub-nav (Overview, App, Files, Domains & SSL, Email, Databases,
 *     Logs, Settings), reusing the per-site install / file-manager / set-primary
 *     capabilities.  URL: `?site=<id|primary>&stab=<subtab>`.
 *
 * Every read/mutation is a real ownership-guarded server action — no mock data.
 * ======================================================================== */

const SECTIONS: [key: string, label: string][] = [
  ["databases", "Databases"],
  ["email", "Email"],
  ["backups", "Backups"],
  ["domains", "Domains & SSL"],
  ["files", "File Manager"],
  ["cron", "Cron"],
  ["logs", "Logs"],
  ["settings", "Settings"],
];
const SECTION_KEYS = SECTIONS.map(([k]) => k);

const SITE_TABS: [key: string, label: string][] = [
  ["overview", "Overview"],
  ["app", "App"],
  ["files", "Files"],
  ["domains", "Domains & SSL"],
  ["email", "Email"],
  ["databases", "Databases"],
  ["logs", "Logs"],
  ["settings", "Settings"],
];
const SITE_TAB_KEYS = SITE_TABS.map(([k]) => k);

type Counts = {
  websites: number;
  dbs: number;
  backups: number;
  emailUsed: number;
  emailCap: number | null;
  subs: number;
  addons: number;
};

export function HostingConsole({
  account,
  initialTab,
  initialPath,
  initialSite,
  initialSiteTab,
}: {
  account: HostingAccountView;
  initialTab?: string;
  initialPath?: string;
  initialSite?: string;
  initialSiteTab?: string;
}) {
  const active = account.status === "ACTIVE";

  // ---- view state --------------------------------------------------------
  const [siteParam, setSiteParam] = useState<string | undefined>(initialSite);
  const [siteTab, setSiteTab] = useState<string>(
    initialSiteTab && SITE_TAB_KEYS.includes(initialSiteTab) ? initialSiteTab : "overview",
  );
  // "console" = the hub; otherwise one of SECTION_KEYS.
  const [section, setSection] = useState<string>(
    initialTab && SECTION_KEYS.includes(initialTab) ? initialTab : "console",
  );

  // Live website list — powers the grid, the switcher and the website-count card.
  const [sites, setSites] = useState<HostingWebsiteView[] | null>(null);
  const refreshSites = useCallback(() => {
    if (!active) { setSites([]); return; }
    listWebsites(account.id).then(setSites).catch(() => setSites([]));
  }, [account.id, active]);
  useEffect(() => { refreshSites(); }, [refreshSites]);

  // ---- URL sync ----------------------------------------------------------
  function pushUrl(params: Record<string, string | undefined>) {
    const qs = new URLSearchParams();
    for (const [k, v] of Object.entries(params)) if (v) qs.set(k, v);
    const s = qs.toString();
    window.history.replaceState(null, "", s ? `?${s}` : window.location.pathname);
  }
  const goHub = useCallback(() => {
    setSiteParam(undefined); setSection("console"); pushUrl({}); window.scrollTo(0, 0);
  }, []);
  const goSection = useCallback((sec: string) => {
    setSiteParam(undefined); setSection(sec); pushUrl({ tab: sec }); window.scrollTo(0, 0);
  }, []);
  const openSite = useCallback((param: string) => {
    setSiteParam(param); setSiteTab("overview"); pushUrl({ site: param, stab: "overview" }); window.scrollTo(0, 0);
  }, []);
  const goSiteTab = useCallback((t: string) => {
    setSiteTab(t); setSiteParam((p) => { pushUrl({ site: p, stab: t }); return p; });
  }, []);

  return (
    <div>
      {siteParam ? (
        <WebsiteDetail
          account={account}
          sites={sites}
          siteParam={siteParam}
          siteTab={siteTab}
          onHub={goHub}
          onSiteTab={goSiteTab}
          onSection={goSection}
          onSitesChanged={refreshSites}
        />
      ) : section === "console" ? (
        <PlanConsole
          account={account}
          sites={sites}
          onOpenSite={openSite}
          onSection={goSection}
          onSitesChanged={refreshSites}
        />
      ) : (
        <PlanSection account={account} section={section} initialPath={initialPath} onHub={goHub} onSection={goSection} />
      )}
    </div>
  );
}

/* ============================================================ plan header === */

function ConsoleHeader({ account, onRenamed }: { account: HostingAccountView; onRenamed?: () => void }) {
  const [editing, setEditing] = useState(false);
  const [value, setValue] = useState(account.name ?? "");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  async function save() {
    setBusy(true); setErr("");
    const r = await renameHostingAccount(account.id, value);
    setBusy(false);
    if (r.error) { setErr(r.error); return; }
    setEditing(false);
    onRenamed?.();
    window.location.reload();
  }

  return (
    <div className="mb-6">
      <div className="flex flex-wrap items-center gap-3">
        {editing ? (
          <div className="flex flex-wrap items-center gap-2">
            <input
              className="input max-w-[280px] text-lg font-semibold"
              value={value}
              maxLength={60}
              autoFocus
              disabled={busy}
              placeholder={`My ${account.planName} workspace`}
              onChange={(e) => setValue(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter") save(); if (e.key === "Escape") setEditing(false); }}
            />
            <button className="btn-primary px-3 py-1.5 text-sm" disabled={busy} onClick={save}>{busy ? "Saving…" : "Save"}</button>
            <button className="btn-secondary px-3 py-1.5 text-sm" disabled={busy} onClick={() => { setEditing(false); setValue(account.name ?? ""); }}>Cancel</button>
          </div>
        ) : (
          <>
            <h1 className="page-title">{account.displayName}</h1>
            <button
              type="button"
              title="Rename this plan"
              onClick={() => setEditing(true)}
              className="rounded-md border border-white/[0.08] bg-white/[0.03] p-1.5 text-slate-400 hover:text-white"
            >
              <svg viewBox="0 0 20 20" fill="none" className="h-3.5 w-3.5"><path d="M13.5 3.5l3 3L7 16l-3.5.5L4 13l9.5-9.5z" stroke="currentColor" strokeWidth="1.4" strokeLinejoin="round" /></svg>
            </button>
            <Badge tone="brand">{account.planName}</Badge>
            <StatusDot status={account.status} />
          </>
        )}
      </div>
      {err && <p className="mt-2 text-sm text-red-400">{err}</p>}
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <a
          href={account.sslActive ? `https://${account.primaryDomain}` : `http://${account.primaryDomain}`}
          target="_blank"
          rel="noreferrer"
          className="rounded-md border border-white/[0.08] bg-white/[0.03] px-2 py-0.5 font-mono text-xs text-slate-300 hover:text-white"
        >
          {account.primaryDomain}
        </a>
        {account.sslActive && <Badge tone="green">HTTPS</Badge>}
        <a href="/dashboard/hosting" className="text-xs text-slate-500 hover:text-slate-300 hover:underline">← All hosting</a>
      </div>
    </div>
  );
}

/* =========================================================== plan console === */

function PlanConsole({
  account,
  sites,
  onOpenSite,
  onSection,
  onSitesChanged,
}: {
  account: HostingAccountView;
  sites: HostingWebsiteView[] | null;
  onOpenSite: (param: string) => void;
  onSection: (sec: string) => void;
  onSitesChanged: () => void;
}) {
  const active = account.status === "ACTIVE";
  const gridRef = useRef<HTMLDivElement>(null);
  const [counts, setCounts] = useState<Counts | null>(null);

  // Live resource counts for the stat-cards — each from its real, ownership-guarded
  // read. Failures degrade to 0 rather than blocking the console.
  useEffect(() => {
    if (!active) return;
    let live = true;
    Promise.all([
      listHostingDatabases(account.id).catch(() => []),
      listHostingBackups(account.id).catch(() => []),
      listHostingSubdomains(account.id).catch(() => []),
      listHostingAddonDomains(account.id).catch(() => []),
      getHostingEmailStatus(account.id).catch(() => null),
    ]).then(([dbs, backups, subs, addons, email]) => {
      if (!live) return;
      setCounts({
        websites: 0, // filled from `sites` below
        dbs: dbs.length,
        backups: backups.length,
        emailUsed: email?.bundled?.mailboxes.length ?? 0,
        emailCap: email?.includedMailboxes ?? null,
        subs: subs.filter((s) => s.status !== "DELETING").length,
        addons: addons.filter((d) => d.status !== "DELETING").length,
      });
    });
    return () => { live = false; };
  }, [account.id, active]);

  const siteCount = sites?.length ?? 0;
  const siteCap = 1 + account.maxSites; // primary + extra sites
  const diskGB = Math.round(account.diskQuotaMB / 1024);
  const usedGB = account.diskUsedMB != null ? account.diskUsedMB / 1024 : null;

  function scrollToGrid() {
    gridRef.current?.scrollIntoView({ behavior: "smooth", block: "start" });
  }

  return (
    <div>
      <div className="flex flex-wrap items-start gap-3">
        <div className="min-w-0 flex-1"><ConsoleHeader account={account} /></div>
        {active && (
          <div className="flex flex-wrap items-center gap-2">
            <button className="btn-secondary text-sm" onClick={() => onSection("settings")}>Upgrade Plan</button>
            <button className="btn-secondary text-sm" onClick={() => onSection("settings")}>Upgrade Storage</button>
            <button className="btn-primary text-sm" onClick={() => onSection("domains")}>+ Add Website</button>
          </div>
        )}
      </div>

      <StatusBanner account={account} />

      {active ? (
        <>
          {/* Resource stat-cards — the primary navigation, scoped to THIS plan. */}
          <div className="mt-6 grid grid-cols-2 gap-3 md:grid-cols-3 xl:grid-cols-5">
            <StatCard icon="🌐" label="Websites" value={String(siteCount)} sub={`/ ${siteCap}`} bar={{ used: siteCount, total: siteCap }} link="Manage →" onClick={scrollToGrid} />
            <StatCard
              icon="💾" label="Storage"
              value={usedGB != null ? usedGB.toFixed(usedGB < 1 ? 2 : 1) : String(diskGB)}
              sub={usedGB != null ? `/ ${diskGB} GB` : "GB SSD"}
              bar={account.diskUsedMB != null ? { used: account.diskUsedMB, total: account.diskQuotaMB } : undefined}
              link="Upgrade →" onClick={() => onSection("settings")}
            />
            <StatCard
              icon="🗄️" label="Databases"
              value={account.maxDatabases > 0 ? String(counts?.dbs ?? 0) : "—"}
              sub={account.maxDatabases > 0 ? `/ ${account.maxDatabases}` : "not on plan"}
              bar={account.maxDatabases > 0 ? { used: counts?.dbs ?? 0, total: account.maxDatabases } : undefined}
              link="Manage →" onClick={() => onSection("databases")}
            />
            <StatCard
              icon="✉️" label="Emails"
              value={String(counts?.emailUsed ?? 0)}
              sub={counts?.emailCap != null ? `/ ${counts.emailCap}` : ""}
              bar={counts?.emailCap ? { used: counts.emailUsed, total: counts.emailCap } : undefined}
              link="Manage →" onClick={() => onSection("email")}
            />
            <StatCard icon="↺" label="Backups" value={String(counts?.backups ?? 0)} sub="on file" link="Manage →" onClick={() => onSection("backups")} />
          </div>

          <div className="mt-8 grid grid-cols-1 gap-6 xl:grid-cols-[1fr_320px] xl:items-start">
            {/* ---- main column: website grid + activity/plan/usage ---- */}
            <div className="min-w-0">
              <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
                <h2 className="text-base font-semibold">Websites</h2>
                <WebsiteSwitcher sites={sites ?? []} onPick={onOpenSite} />
              </div>
              <div ref={gridRef} className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                {sites === null ? (
                  <p className="text-sm text-slate-500">Loading websites…</p>
                ) : (
                  <>
                    {sites.map((w) => (
                      <WebsiteCard key={w.key} site={w} onManage={() => onOpenSite(w.id ?? "primary")} onSection={onSection} onOpenSite={onOpenSite} onSitesChanged={onSitesChanged} accountId={account.id} />
                    ))}
                    <button
                      type="button"
                      onClick={() => onSection("domains")}
                      className="flex min-h-[168px] flex-col items-center justify-center gap-2 rounded-2xl border border-dashed border-white/15 p-6 text-center text-slate-400 transition-colors hover:border-brand-400 hover:text-white"
                    >
                      <span className="grid h-11 w-11 place-items-center rounded-xl border border-brand-500/30 bg-brand-500/10 text-xl text-brand-300">+</span>
                      <span className="font-semibold">Add New Website</span>
                      <span className="text-xs text-slate-500">Attach a subdomain or domain, then install an app</span>
                    </button>
                  </>
                )}
              </div>

              <div className="mt-6 grid grid-cols-1 gap-4 lg:grid-cols-2">
                <ActivityCard accountId={account.id} onSection={onSection} />
                <PlanInfoCard account={account} counts={counts} siteCount={siteCount} siteCap={siteCap} onSection={onSection} />
              </div>

              <ResourceUsageCard account={account} counts={counts} />

              {/* Plan-wide app logins (one per website). */}
              <div className="mt-6"><AppCredentials accountId={account.id} /></div>
            </div>

            {/* ---- slim right rail: connection + access + support ---- */}
            <aside className="flex flex-col gap-4">
              <ConnectionCard account={account} />
              <div className="card">
                <h3 className="mb-2 font-semibold">Need help?</h3>
                <p className="mb-3 text-sm text-slate-400">Our support team can help with anything on this plan.</p>
                <a href="/dashboard/support" className="btn-primary block w-full text-center text-sm">Contact support</a>
              </div>
            </aside>
          </div>
        </>
      ) : (
        <div className="mt-6"><ConsoleHeaderNotReady /></div>
      )}
    </div>
  );
}

function ConsoleHeaderNotReady() {
  return (
    <div className="card py-12 text-center">
      <h2 className="font-semibold">Still being set up</h2>
      <p className="mx-auto mt-2 max-w-md text-sm text-slate-400">
        This account is provisioning — it usually takes under a minute. Your console lights up once it’s active. Refresh to check.
      </p>
    </div>
  );
}

/* ------------------------------------------------------------ stat cards --- */

function StatCard({
  icon, label, value, sub, bar, link, onClick,
}: {
  icon: string; label: string; value: string; sub?: string;
  bar?: { used: number; total: number }; link: string; onClick: () => void;
}) {
  const pct = bar && bar.total > 0 ? Math.min(100, Math.round((bar.used / bar.total) * 100)) : null;
  return (
    <button type="button" onClick={onClick} className="card p-4 text-left transition-colors hover:border-brand-400/50">
      <div className="flex items-center gap-2">
        <span className="grid h-8 w-8 place-items-center rounded-lg border border-white/[0.06] bg-white/[0.04] text-sm">{icon}</span>
        <span className="text-xs text-slate-400">{label}</span>
      </div>
      <div className="my-2 text-xl font-bold tracking-tight">
        {value} {sub && <span className="text-xs font-normal text-slate-500">{sub}</span>}
      </div>
      {pct !== null ? (
        <div className="h-1.5 w-full overflow-hidden rounded-full bg-white/[0.06]">
          <div className={`h-full rounded-full ${pct >= 100 ? "bg-amber-400" : "bg-gradient-to-r from-accent-blue to-brand-500"}`} style={{ width: `${Math.max(4, pct)}%` }} />
        </div>
      ) : (
        <div className="h-1.5" />
      )}
      <span className="mt-2.5 inline-block text-xs font-semibold text-brand-300">{link}</span>
    </button>
  );
}

/* --------------------------------------------------------- website cards --- */

function targetOf(w: HostingWebsiteView): SiteTarget {
  if (w.kind === "subdomain" && w.id) return { kind: "subdomain", id: w.id };
  if (w.kind === "addon" && w.id) return { kind: "addon", id: w.id };
  return { kind: "primary" };
}

const KIND_LABEL: Record<HostingWebsiteView["kind"], string> = { primary: "Primary", subdomain: "Subdomain", addon: "Addon domain" };

function WebsiteCard({
  site, accountId, onManage, onSection, onOpenSite, onSitesChanged,
}: {
  site: HostingWebsiteView; accountId: string; onManage: () => void;
  onSection: (s: string) => void; onOpenSite: (p: string) => void; onSitesChanged: () => void;
}) {
  const [menu, setMenu] = useState(false);
  const [busy, setBusy] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  const settling = site.status === "PENDING" || site.status === "DELETING";

  useEffect(() => {
    function onDoc(e: MouseEvent) { if (ref.current && !ref.current.contains(e.target as Node)) setMenu(false); }
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, []);

  async function promote() {
    if (!site.id) return;
    setMenu(false);
    if (!confirm(`Make ${site.hostname} your primary domain? Your main website (public_html) will answer on ${site.hostname}, and your old address keeps working as an alias.`)) return;
    setBusy(true);
    const r = await setPrimaryHostingDomain(accountId, site.id);
    setBusy(false);
    if (r.error) alert(r.error); else onSitesChanged();
  }
  async function remove() {
    if (!site.id) return;
    setMenu(false);
    if (!confirm(`Delete ${site.hostname}? Its files will be removed.`)) return;
    setBusy(true);
    const r = site.kind === "subdomain" ? await deleteSubdomain(site.id) : await deleteAddonDomain(site.id);
    setBusy(false);
    if (r.error) alert(r.error); else onSitesChanged();
  }

  const isWp = (site.installedApp ?? "").toLowerCase().includes("wordpress");

  return (
    <div className="overflow-hidden rounded-2xl border border-white/[0.06] bg-white/[0.02] transition-all hover:-translate-y-0.5 hover:border-brand-400/40">
      <div className="flex gap-3 p-4">
        <div className="grid h-14 w-16 shrink-0 place-items-center rounded-xl border border-white/[0.06] bg-gradient-to-br from-accent-blue/15 to-brand-500/15 text-2xl">
          {isWp ? "🅦" : site.installedApp ? "📦" : "📄"}
        </div>
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-center gap-1.5">
            <a
              href={site.sslActive ? `https://${site.hostname}` : `http://${site.hostname}`}
              target="_blank"
              rel="noreferrer"
              className="max-w-[160px] truncate font-mono text-sm font-medium text-slate-100 hover:underline"
              title={site.hostname}
            >
              {site.hostname}
            </a>
            {site.kind === "primary" && <Badge tone="slate">Primary</Badge>}
          </div>
          <div className="mt-1.5 flex items-center gap-2 text-xs text-slate-400">
            {site.status === "ACTIVE"
              ? <span className="inline-flex items-center gap-1.5 text-emerald-300"><span className="h-1.5 w-1.5 rounded-full bg-emerald-400" />Active</span>
              : <StatusDot status={site.status} />}
            <span className="text-slate-500">·</span>
            <span>{site.installedApp ?? "No app"}</span>
          </div>
        </div>
      </div>
      <div className="flex flex-wrap gap-x-4 gap-y-1 px-4 pb-3 text-[11px] text-slate-500">
        <span>{site.sslActive ? "🔒 HTTPS" : "⚠ HTTP"}</span>
        <span>PHP {site.phpVersion}</span>
        <span className="truncate">{site.fileManagerPath}</span>
      </div>
      <div className="relative flex gap-2 border-t border-white/[0.06] bg-white/[0.02] p-3" ref={ref}>
        <button className="btn-primary flex-1 py-1.5 text-xs" disabled={busy || settling} onClick={onManage}>{busy ? "Working…" : "Manage"}</button>
        <button className="btn-secondary px-3 py-1.5 text-xs" disabled={busy || settling} onClick={() => setMenu((m) => !m)} aria-label="More actions">⋯</button>
        {menu && (
          <div className="absolute bottom-full right-3 z-20 mb-1 w-52 overflow-hidden rounded-xl border border-white/[0.08] bg-navy-900/95 p-1 shadow-xl backdrop-blur-md">
            <MenuItem onClick={() => { setMenu(false); onManage(); }}>Open console</MenuItem>
            <MenuItem onClick={() => { setMenu(false); onOpenSite(site.id ?? "primary"); }}>Manage files</MenuItem>
            <a href={site.sslActive ? `https://${site.hostname}` : `http://${site.hostname}`} target="_blank" rel="noreferrer" className="block rounded-lg px-3 py-2 text-sm text-slate-200 hover:bg-white/[0.05]">Visit site ↗</a>
            {site.canSetPrimary && <MenuItem onClick={promote}>Set as primary</MenuItem>}
            {(site.kind === "subdomain" || site.kind === "addon") && (
              <button type="button" onClick={remove} className="block w-full rounded-lg px-3 py-2 text-left text-sm text-red-300 hover:bg-red-500/10">Delete website</button>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

function MenuItem({ children, onClick }: { children: ReactNode; onClick: () => void }) {
  return <button type="button" onClick={onClick} className="block w-full rounded-lg px-3 py-2 text-left text-sm text-slate-200 hover:bg-white/[0.05]">{children}</button>;
}

/* ------------------------------------------------------- website switcher --- */

function WebsiteSwitcher({ sites, onPick }: { sites: HostingWebsiteView[]; onPick: (siteParam: string) => void }) {
  const [q, setQ] = useState("");
  const [open, setOpen] = useState(false);
  const boxRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function onDoc(e: MouseEvent) { if (boxRef.current && !boxRef.current.contains(e.target as Node)) setOpen(false); }
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, []);

  const needle = q.trim().toLowerCase();
  const matches = needle ? sites.filter((s) => s.hostname.toLowerCase().includes(needle)) : sites;

  return (
    <div ref={boxRef} className="relative w-full max-w-xs">
      <div className="flex items-center gap-2 rounded-xl border border-white/[0.08] bg-navy-900/70 px-3 py-1.5 backdrop-blur-md">
        <svg viewBox="0 0 20 20" fill="none" className="h-4 w-4 shrink-0 text-slate-500"><path d="M9 3a6 6 0 104.472 10.03l3.249 3.248a.75.75 0 101.06-1.06l-3.248-3.249A6 6 0 009 3z" fill="currentColor" /></svg>
        <input
          className="w-full bg-transparent text-sm text-slate-100 placeholder:text-slate-500 focus:outline-none"
          placeholder={`Search websites${sites.length ? ` (${sites.length})` : ""}…`}
          value={q}
          onFocus={() => setOpen(true)}
          onChange={(e) => { setQ(e.target.value); setOpen(true); }}
        />
      </div>
      {open && (
        <div className="absolute z-20 mt-1 max-h-72 w-full overflow-auto rounded-xl border border-white/[0.08] bg-navy-900/95 p-1 shadow-xl backdrop-blur-md">
          {matches.length === 0 ? (
            <p className="px-3 py-2 text-sm text-slate-500">No matching websites.</p>
          ) : (
            matches.map((w) => (
              <button
                key={w.key}
                type="button"
                onMouseDown={(e) => { e.preventDefault(); onPick(w.id ?? "primary"); setOpen(false); setQ(""); }}
                className="flex w-full items-center justify-between gap-2 rounded-lg px-3 py-2 text-left hover:bg-white/[0.05]"
              >
                <span className="min-w-0 truncate font-mono text-sm text-slate-100">{w.hostname}</span>
                <Badge tone={w.kind === "primary" ? "brand" : "slate"}>{KIND_LABEL[w.kind]}</Badge>
              </button>
            ))
          )}
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------- bottom-row cards --- */

const LOG_LABELS: Record<string, string> = {
  PHP_SWITCH: "PHP version change", WORDPRESS_INSTALL: "WordPress install", APP_INSTALL: "App install",
  BACKUP: "Backup", RESTORE: "Restore", CREATE_SUBDOMAIN: "Subdomain created", DELETE_SUBDOMAIN: "Subdomain removed",
  CREATE_ADDON_DOMAIN: "Addon domain added", DELETE_ADDON_DOMAIN: "Domain removed", CREATE_CRON: "Cron job created",
  DELETE_CRON: "Cron job removed", ENSURE_DBMGR: "Database manager", APPLY_PLAN_LIMITS: "Plan update",
  SET_PRIMARY_DOMAIN: "Primary domain change",
};

type LogRow = { id: string; kind: string; status: string; error: string | null; createdAt: string; updatedAt: string };

function useTaskLog(accountId: string) {
  const [rows, setRows] = useState<LogRow[] | null>(null);
  useEffect(() => {
    let stop = false;
    const load = () => listHostingTaskLog(accountId).then((r) => { if (!stop) setRows(r); }).catch(() => { if (!stop) setRows([]); });
    load();
    const t = setInterval(load, 8000);
    return () => { stop = true; clearInterval(t); };
  }, [accountId]);
  return rows;
}

function ActivityCard({ accountId, onSection }: { accountId: string; onSection: (s: string) => void }) {
  const rows = useTaskLog(accountId);
  return (
    <div className="card">
      <h3 className="mb-3 flex items-center gap-2 font-semibold">
        Recent activity
        <button type="button" onClick={() => onSection("logs")} className="ml-auto text-xs font-semibold text-brand-300 hover:underline">View all logs →</button>
      </h3>
      {rows === null ? (
        <p className="text-sm text-slate-500">Loading…</p>
      ) : rows.length === 0 ? (
        <p className="text-sm text-slate-500">No activity yet.</p>
      ) : (
        <ul className="space-y-0">
          {rows.slice(0, 6).map((t) => (
            <li key={t.id} className="flex items-center gap-3 border-t border-white/[0.06] py-2 text-sm first:border-t-0">
              <span className="min-w-0 flex-1 truncate text-slate-300">{LOG_LABELS[t.kind] ?? t.kind}</span>
              <span className={`text-xs font-medium ${t.status === "FAILED" ? "text-red-300" : t.status === "DONE" ? "text-emerald-300" : "text-amber-300"}`}>{t.status.toLowerCase()}</span>
              <span className="shrink-0 text-xs text-slate-500">{new Date(t.createdAt).toLocaleDateString()}</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

function PlanInfoCard({
  account, counts, siteCount, siteCap, onSection,
}: {
  account: HostingAccountView; counts: Counts | null; siteCount: number; siteCap: number; onSection: (s: string) => void;
}) {
  const diskGB = Math.round(account.diskQuotaMB / 1024);
  return (
    <div className="card">
      <h3 className="mb-3 font-semibold">Plan</h3>
      <dl className="space-y-2 text-sm">
        <Row k="Plan" v={<span className="flex items-center gap-2">{account.planName} <Badge tone="brand">plan</Badge></span>} />
        <Row k="Status" v={<StatusDot status={account.status} />} />
        <Row k="Websites" v={`${siteCount} of ${siteCap}`} />
        <Row k="Storage" v={`${diskGB} GB${account.extraDiskGB > 0 ? ` (+${account.extraDiskGB} GB added)` : ""}`} />
        <Row k="Databases" v={account.maxDatabases > 0 ? `${counts?.dbs ?? 0} of ${account.maxDatabases}` : "Not on this plan"} />
        <Row k="Mailboxes" v={counts?.emailCap != null ? `${counts.emailUsed} of ${counts.emailCap}` : "—"} />
        <Row k="PHP" v={<span className="font-mono text-xs">{account.phpVersion}</span>} />
        {account.expiresAt && <Row k="Renews" v={new Date(account.expiresAt).toISOString().slice(0, 10)} />}
      </dl>
      <button className="btn-secondary mt-4 w-full text-sm" onClick={() => onSection("settings")}>Manage plan &amp; upgrades</button>
    </div>
  );
}

function Row({ k, v }: { k: string; v: ReactNode }) {
  return (
    <div className="flex items-center justify-between gap-2 border-t border-white/[0.06] py-1.5 first:border-t-0">
      <dt className="text-slate-400">{k}</dt>
      <dd className="text-right font-medium">{v}</dd>
    </div>
  );
}

/** Real resource usage only — storage + inodes come off the account's usage sweep.
 *  CPU / memory / bandwidth aren't measured, so they're intentionally absent. */
function ResourceUsageCard({ account, counts }: { account: HostingAccountView; counts: Counts | null }) {
  const hasUsage = account.diskUsedMB != null || account.inodesUsed != null;
  if (!hasUsage) return null;
  const diskGB = Math.round(account.diskQuotaMB / 1024);
  const extraSites = counts ? counts.subs + counts.addons : 0;
  return (
    <div className="mt-6 card">
      <h3 className="mb-4 font-semibold">Resource usage {account.usageAt && <span className="text-xs font-normal text-slate-500">· measured {new Date(account.usageAt).toLocaleString()}</span>}</h3>
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        {account.diskUsedMB != null && (
          <QuotaTile label="Storage" primary={`${(account.diskUsedMB / 1024).toFixed(account.diskUsedMB < 1024 ? 2 : 1)} of ${diskGB} GB`} bar={{ used: account.diskUsedMB, total: account.diskQuotaMB }} />
        )}
        {account.inodesUsed != null && (
          <QuotaTile label="Inodes (files)" primary={account.inodesUsed.toLocaleString()} note="Total files & folders" />
        )}
        <QuotaTile label="Extra sites" primary={`${extraSites} of ${account.maxSites}`} bar={{ used: extraSites, total: account.maxSites }} note="Subdomains + addon domains" />
        {account.maxDatabases > 0 && (
          <QuotaTile label="Databases" primary={`${counts?.dbs ?? 0} of ${account.maxDatabases}`} bar={{ used: counts?.dbs ?? 0, total: account.maxDatabases }} />
        )}
      </div>
    </div>
  );
}

/* ------------------------------------------------------- connection rail --- */

function ConnectionCard({ account }: { account: HostingAccountView }) {
  const [a, setA] = useState(account);
  const [sftpPw, setSftpPw] = useState<string | null>(null);
  const [recheckBusy, setRecheckBusy] = useState(false);

  const active = a.status === "ACTIVE";

  useEffect(() => {
    if (!active || a.sslActive) return;
    const t = setInterval(() => { getHostingAccount(a.id).then((fresh) => { if (fresh) setA(fresh); }).catch(() => {}); }, 15000);
    return () => clearInterval(t);
  }, [a.id, active, a.sslActive]);

  async function recheck() {
    setRecheckBusy(true);
    const r = await recheckHostingHealth(a.id);
    if (r.error) { alert(r.error); setRecheckBusy(false); return; }
    let tries = 0;
    const poll = setInterval(() => {
      tries++;
      getHostingAccount(a.id).then((fresh) => { if (fresh) setA(fresh); }).catch(() => {});
      if (tries >= 9) { clearInterval(poll); setRecheckBusy(false); }
    }, 5000);
  }

  async function reveal() {
    const res = await revealHostingSftpPassword(a.id);
    if (res.password) setSftpPw(res.password); else if (res.error) alert(res.error);
  }

  if (!active) return null;

  return (
    <div className="card">
      <div className="mb-3 flex items-center justify-between gap-2">
        <h3 className="font-semibold">{a.isFreeSubdomain ? "Your website" : "Point your domain"}</h3>
        <button type="button" className="btn-secondary px-2.5 py-1 text-xs" disabled={recheckBusy} onClick={recheck}>
          {recheckBusy ? "Checking…" : a.sslActive ? "Check now" : a.isFreeSubdomain ? "Refresh" : "Go live"}
        </button>
      </div>
      {!a.isFreeSubdomain && !a.sslActive && (
        <p className="mb-2 text-xs text-slate-400">
          Create an <span className="font-mono text-slate-200">A</span> record for <span className="font-mono text-slate-200">{a.primaryDomain}</span> → <span className="font-mono text-brand-200">{a.pointToA}</span>
          {a.pointToCname && <> (or a <span className="font-mono text-slate-200">CNAME</span> to <span className="font-mono text-slate-200">{a.pointToCname}</span>)</>}.
        </p>
      )}
      <DnsStepper account={a} />
      <div className="mt-4 border-t border-white/[0.06] pt-3">
        <p className="mb-1 text-xs font-semibold uppercase tracking-wide text-slate-500">SFTP</p>
        <p className="text-sm text-slate-400"><span className="font-mono text-slate-200">{a.username}</span>@{a.pointToA}</p>
        {sftpPw ? (
          <p className="mt-1 break-all font-mono text-sm text-brand-200">{sftpPw}</p>
        ) : (
          <button className="mt-1 text-xs text-brand-300 hover:underline" onClick={reveal}>show password</button>
        )}
      </div>
    </div>
  );
}

/* ----------------------------------------------------------- DNS stepper --- */

function DnsStepper({ account }: { account: HostingAccountView }) {
  const checked = account.healthCheckedAt != null || account.serveHttpOk != null;
  const serving = account.serveHttpOk === true || account.serveHttpsOk === true;
  const verified = account.sslActive && account.serveHttpsOk !== false;
  const state: "verified" | "issuing" | "dns" | "pending" = verified ? "verified" : serving ? "issuing" : checked ? "dns" : "pending";
  const free = account.isFreeSubdomain;
  const steps = [
    { label: free ? "DNS ready" : "Point domain", done: true },
    { label: "Site live", done: state === "issuing" || state === "verified" },
    { label: "HTTPS verified", done: state === "verified" },
  ];
  const headline =
    account.healthNote ??
    (state === "verified" ? "HTTPS live — verified" : state === "issuing" ? "HTTP live, HTTPS issuing" : state === "dns" ? "DNS not detected yet" : "Not checked yet");
  const tone = state === "verified" ? "text-emerald-300" : state === "dns" ? "text-slate-400" : "text-amber-300";
  return (
    <div>
      <div className="flex items-center">
        {steps.map((s, i) => (
          <div key={s.label} className="flex flex-1 items-center last:flex-none">
            <span className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] ${s.done ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300" : "border-amber-500/40 bg-amber-500/10 text-amber-300"}`}>{s.done ? "✓" : i + 1}</span>
            {i < steps.length - 1 && <div className={`mx-2 h-px flex-1 ${steps[i + 1].done ? "bg-emerald-500/40" : "bg-white/10"}`} />}
          </div>
        ))}
      </div>
      <div className="mt-1.5 flex items-start justify-between text-[11px]">
        {steps.map((s) => (
          <div key={s.label} className="flex-1 text-center first:text-left last:text-right">
            <p className={s.done ? "text-emerald-300" : "text-slate-400"}>{s.label}</p>
          </div>
        ))}
      </div>
      <p className={`mt-2 text-xs font-medium ${tone}`}>{headline}</p>
    </div>
  );
}

