  if (sites === null) return <div className="card py-12 text-center text-sm text-slate-500">Loading website…</div>;
  if (!site) {
    return (
      <div className="card py-12 text-center">
        <p className="text-sm text-slate-400">That website is no longer on this plan.</p>
