  }

  const isWp = (site.installedApp ?? "").toLowerCase().includes("wordpress");

  let body: ReactNode;
  switch (siteTab) {
    case "app": body = <SiteAppTab account={account} site={site} onSitesChanged={onSitesChanged} />; break;
    case "files": body = <FileManager accountId={account.id} initialPath={site.fileManagerPath} />; break;
    case "domains": body = <SiteDomainsTab account={account} site={site} onSection={onSection} onSitesChanged={onSitesChanged} />; break;
    case "email": body = <ManagedAtPlan section="email" label="Email" onSection={onSection} note="Mailboxes are provisioned per plan on a domain you choose (which can be this website's domain). Manage them in the plan Email section." />; break;
    case "databases": body = <ManagedAtPlan section="databases" label="Databases" onSection={onSection} note="Databases belong to the plan, not a single website — an app on any site can connect to any of them. Manage them in the plan Databases section." />; break;
    case "logs": body = <LogsPanel accountId={account.id} />; break;
    case "settings": body = <SiteSettingsTab account={account} site={site} onSection={onSection} onSitesChanged={onSitesChanged} onHub={onHub} />; break;
