  }

  return (
    <div>
      <div className="mb-3 text-xs text-slate-500">
        <button type="button" className="hover:text-slate-300" onClick={onHub}>Hosting</button>
        {" › "}
        <button type="button" className="hover:text-slate-300" onClick={onHub}>{account.displayName}</button>
