function SiteDomainsTab({
  account, site, onSection, onSitesChanged,
}: {
  account: HostingAccountView; site: HostingWebsiteView; onSection: (s: string) => void; onSitesChanged: () => void;
}) {
  const [busy, setBusy] = useState(false);
  async function promote() {
    if (!site.id) return;
    if (!confirm(`Make ${site.hostname} your primary domain? Your main website (public_html) will answer on ${site.hostname}, and your old address keeps working as an alias.`)) return;
    setBusy(true);
    const r = await setPrimaryHostingDomain(account.id, site.id);
    setBusy(false);
    if (r.error) alert(r.error); else onSitesChanged();
  }
  return (
    <div className="card max-w-2xl">
      <h3 className="mb-3 font-semibold">Domains &amp; SSL</h3>
      <dl className="space-y-2 text-sm">
        <Row k="Serving on" v={<span className="font-mono text-xs">{site.hostname}</span>} />
        <Row k="HTTPS" v={site.sslActive ? <span className="text-emerald-300">Active (auto-renew)</span> : <span className="text-amber-300">Issuing — automatic once DNS resolves</span>} />
        <Row k="Type" v={KIND_LABEL[site.kind]} />
      </dl>
      <div className="mt-4 flex flex-wrap gap-2">
        {site.canSetPrimary && <button className="btn-secondary text-sm" disabled={busy} onClick={promote}>⭐ Make primary domain</button>}
        <button className="btn-secondary text-sm" onClick={() => onSection("domains")}>Add / manage domains</button>
      </div>
      {site.kind === "primary" && <p className="mt-3 text-xs text-slate-500">This is your primary domain. Add more subdomains or addon domains from the plan Domains section.</p>}
    </div>
  );
}

function SiteSettingsTab({
  account, site, onSection, onSitesChanged, onHub,
}: {
  account: HostingAccountView; site: HostingWebsiteView; onSection: (s: string) => void; onSitesChanged: () => void; onHub: () => void;
}) {
  const [busy, setBusy] = useState(false);
  async function remove() {
    if (!site.id) return;
    if (!confirm(`Delete ${site.hostname}? Its files will be removed.`)) return;
    setBusy(true);
    const r = site.kind === "subdomain" ? await deleteSubdomain(site.id) : await deleteAddonDomain(site.id);
    setBusy(false);
    if (r.error) { alert(r.error); return; }
    onSitesChanged();
    onHub();
  }
  return (
    <div className="space-y-6">
      <div className="card max-w-2xl">
        <h3 className="mb-1 font-semibold">Runtime</h3>
        <p className="text-sm text-slate-400">PHP <span className="font-mono text-slate-200">{site.phpVersion}</span> — the PHP runtime applies to every website on the plan. Change it in the plan <button type="button" className="text-brand-300 hover:underline" onClick={() => onSection("settings")}>Settings</button>.</p>
      </div>
      {site.kind === "primary" ? (
        <div className="card max-w-2xl">
          <h3 className="mb-1 font-semibold">Primary website</h3>
          <p className="text-sm text-slate-400">This is your plan’s primary website and can’t be deleted. Promote an addon domain to primary to change which site answers on <span className="font-mono text-slate-200">public_html</span>.</p>
        </div>
      ) : (
        <div className="card max-w-2xl border-red-500/20">
          <h3 className="mb-1 font-semibold text-red-300">Delete this website</h3>
          <p className="mb-3 text-sm text-slate-400">Removes {site.hostname} and its files from the plan. This can’t be undone.</p>
          <button className="btn-danger text-sm" disabled={busy} onClick={remove}>{busy ? "Deleting…" : `Delete ${site.hostname}`}</button>
        </div>
      )}
    </div>
  );
}

function ManagedAtPlan({ section, label, note, onSection }: { section: string; label: string; note: string; onSection: (s: string) => void }) {
  return (
    <div className="card max-w-2xl">
      <h3 className="mb-1 font-semibold">{label} — managed at plan level</h3>
      <p className="mb-4 text-sm text-slate-400">{note}</p>
      <button className="btn-primary text-sm" onClick={() => onSection(section)}>Open plan {label} →</button>
    </div>
  );
}

import { notFound } from "next/navigation";
import { getHostingAccount } from "@/lib/actions-hosting";
import { HostingConsole } from "@/components/customer/hosting/HostingConsole";

export const dynamic = "force-dynamic";

export default async function HostingAccountPage({
  params,
  searchParams,
}: {
  params: Promise<{ id: string }>;
  searchParams: Promise<{ tab?: string; path?: string; site?: string; stab?: string }>;
}) {
  const [{ id }, { tab, path, site, stab }] = await Promise.all([params, searchParams]);

  // getHostingAccount enforces owner-or-admin (throws) and returns null if missing.
  let account: Awaited<ReturnType<typeof getHostingAccount>> = null;
  try {
    account = await getHostingAccount(id);
  } catch {
    notFound();
  }
  if (!account) notFound();

  return (
    <HostingConsole
      account={account}
      initialTab={tab}
      initialPath={path}
      initialSite={site}
      initialSiteTab={stab}
    />
  );
}

